import sys
from math import isqrt
def prime(x):
    if x < 2:
        return False
    for d in range(2, isqrt(x) + 1):
        if x % d == 0:
            return False
    return True
a = list(map(int, sys.stdin.read().split()))
values = a[1:1+a[0]]
answer = -1
cache = {}
for i in range(1, len(values)-1):
    for x in (values[i-1], values[i+1]):
        if x not in cache:
            cache[x] = prime(x)
    if cache[values[i-1]] and cache[values[i+1]]:
        answer = values[i]
        break
print(answer)

