binary-string-ops:
import sys

def solve():
    s = sys.stdin.read().strip()
    if not s:
        print(-1)
        return
    res = int(s[0])
    i = 1
    while i < len(s):
        op = s[i]
        nxt = int(s[i+1])
        if op == "A":
            res = res & nxt
        elif op == "B":
            res = res | nxt
        elif op == "C":
            res = res ^ nxt
        i += 2
    print(res)

solve()

password-checker:
import sys

def solve():
    s = sys.stdin.read().strip()
    if len(s) < 4 or s[0].isdigit():
        print(0)
        return
    has_digit = False
    has_upper = False
    for ch in s:
        if ch == " " or ch == "/":
            print(0)
            return
        if ch.isdigit():
            has_digit = True
        elif ch.isupper():
            has_upper = True
    print(1 if (has_digit and has_upper) else 0)

solve()

