pairwise-difference:
import sys

def solve():
    lines = sys.stdin.read().split()
    if not lines:
        print(0)
        return
    n = int(lines[0])
    arr = [int(x) for x in lines[1:1+n]]
    if n < 2:
        print(0)
        return
    min_val = arr[0]
    max_diff = 0
    for i in range(1, n):
        if arr[i] - min_val > max_diff:
            max_diff = arr[i] - min_val
        if arr[i] < min_val:
            min_val = arr[i]
    print(max_diff)

solve()
